import numpy as np

# Embedding đồ chơi 3 chiều: [hoàng gia, nam, nữ]
vocab = {
    "king":  np.array([1.0, 1.0, 0.0]),
    "queen": np.array([1.0, 0.0, 1.0]),
    "man":   np.array([0.0, 1.0, 0.0]),
    "woman": np.array([0.0, 0.0, 1.0]),
    "apple": np.array([0.1, 0.1, 0.1]),
}

def cosine(a, b):
    return float(a @ b / (np.linalg.norm(a) * np.linalg.norm(b)))

def nearest(vec, exclude=()):
    scores = {w: cosine(vec, v) for w, v in vocab.items() if w not in exclude}
    return max(scores, key=scores.get)

analogy = vocab["king"] - vocab["man"] + vocab["woman"]
print(nearest(analogy, exclude={"king", "man", "woman"}))     # queen

